INSERT INTO exam_questions (subject, grade, question_type, question_text, options, answer, explanation, difficulty, topic)
VALUES
  ('ศิลปะ', 'ป.4', 'mcq', 'ข้อใดเป็นความแตกต่างที่สำคัญที่สุดระหว่าง ''รูปร่าง'' (Shape) กับ ''รูปทรง'' (Form)', '["รูปร่างมี 2 มิติ (กว้างและยาว) ส่วนรูปทรงมี 3 มิติ (มีความหนาหรือความลึก)","รูปร่างมีสีสัน แต่รูปทรงไม่มีสี","รูปร่างมี 3 มิติ ส่วนรูปทรงมี 2 มิติ","รูปร่างใช้ดินปั้น ส่วนรูปทรงใช้วาดภาพ"]'::jsonb, '0'::jsonb, 'รูปร่าง (Shape) เป็นภาพ 2 มิติ มีเฉพาะความกว้างและความยาว ส่วนรูปทรง (Form) เป็นภาพ 3 มิติ มีความกว้าง ยาว หนา ลึก และปริมาตร', 'easy', '[ศ 1.1 ป.4/1] รูปร่างและรูปทรง'),
  ('ศิลปะ', 'ป.4', 'mcq', 'กลุ่มสีในข้อใดจัดอยู่ใน ''วรรณะร้อน'' (Warm Tone) ทั้งหมด', '["สีแดง สีส้ม สีเหลือง","สีน้ำเงิน สีฟ้า สีคราม","สีเขียว สีม่วง สีคราม","สีขาว สีเทา สีดำ"]'::jsonb, '0'::jsonb, 'วรรณะร้อนประกอบด้วย สีเหลือง สีส้มเหลือง สีส้ม สีส้มแดง สีแดง สีม่วงแดง ให้ความรู้สึกอบอุ่น ร้อนแรง ตื่นเต้น', 'easy', '[ศ 1.1 ป.4/2] วรรณะของสี (Warm & Cool Tones)'),
  ('ศิลปะ', 'ป.4', 'mcq', '''เส้นตรงแนวตั้ง'' ให้ความรู้สึกอย่างไรในงานทัศนศิลป์', '["มั่นคง แข็งแรง สง่างาม","เคลื่อนไหว นุ่มนวล อ่อนไหว","สงบ ราบเรียบ กว้างขวาง","สับสน วุ่นวาย อันตราย"]'::jsonb, '0'::jsonb, 'เส้นตรงแนวตั้งให้ความรู้สึกสง่างาม มั่นคง แข็งแรง และตั้งตรงสูงตระหง่าน', 'easy', '[ศ 1.1 ป.4/3] ทัศนธาตุ (เส้น)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'วัสดุในข้อใดเป็น ''วัสดุธรรมชาติ'' ที่นิยมนำมาใช้เป็นแม่พิมพ์ในการพิมพ์ภาพ', '["ใบไม้ ก้านกล้วย และหัวมันฝรั่ง","ฝาขวดน้ำพลาสติก","เชือกฟางพลาสติก","โฟมสังเคราะห์"]'::jsonb, '0'::jsonb, 'ใบไม้ กิ่งไม้ ก้านกล้วย ลายนิ้วมือ ผลไม้ เป็นวัสดุที่ได้จากธรรมชาติ สามารถนำมาทาสีแล้วกดพิมพ์ลงบนกระดาษได้', 'easy', '[ศ 1.1 ป.4/4] งานภาพพิมพ์จากวัสดุธรรมชาติ'),
  ('ศิลปะ', 'ป.4', 'mcq', 'งานปั้นที่สามารถมองเห็นได้รอบด้าน 360 องศา เรียกว่างานปั้นประเภทใด', '["งานปั้นลอยตัว","งานปั้นนูนต่ำ","งานปั้นนูนสูง","งานปั้นแบน"]'::jsonb, '0'::jsonb, 'งานปั้นลอยตัว (Round-relief) เป็นงานประติมากรรมที่สามารถมองเห็นได้รอบด้านทุกทิศทาง เช่น อนุสาวรีย์ พระพุทธรูป ตุ๊กตาดินเผา', 'easy', '[ศ 1.1 ป.4/5] ประเภทของงานปั้น'),
  ('ศิลปะ', 'ป.4', 'mcq', 'แม่ลายไทยพื้นฐาน 4 หมวด ได้แก่ข้อใดบ้าง', '["กนก กะบี่ กระบี่ กระบี่ (กนก นารี กระบี่ คชะ)","ดอกไม้ นก ปลา ม้า","วงกลม สามเหลี่ยม สี่เหลี่ยม วงรี","เส้นตรง เส้นโค้ง เส้นคลื่น เส้นหยัก"]'::jsonb, '0'::jsonb, 'แม่ลายไทยพื้นฐาน 4 หมวด ได้แก่ กนก (ลายเปลวไฟ/ต้นไม้), นารี (ภาพมนุษย์เทวดา), กระบี่ (ลิง/สัตว์ป่า), และคชะ (ช้าง/สัตว์หิมพานต์)', 'easy', '[ศ 1.2 ป.4/1] ศิลปวัฒนธรรมท้องถิ่น (ลายไทย)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'เครื่องดนตรีไทยแบ่งออกเป็น 4 ประเภท ได้แก่ประเภทใดบ้าง', '["ดีด สี ตี เป่า","เคาะ ดีด เป่า เขย่า","เป่า ตี สี กด","สาย ลม เคาะ ทองเหลือง"]'::jsonb, '0'::jsonb, 'เครื่องดนตรีไทยจำแนกตามวิธีการทำให้เกิดเสียงได้ 4 หมวด คือ เครื่องดีด (จะเข้ กระจับปี่), เครื่องสี (ซอ), เครื่องตี (ระนาด ฆ้องวง), และเครื่องเป่า (ขลุ่ย ปี่)', 'easy', '[ศ 2.1 ป.4/1] ประเภทของเครื่องดนตรีไทย'),
  ('ศิลปะ', 'ป.4', 'mcq', 'เครื่องดนตรีไทยในข้อใดจัดอยู่ในกลุ่ม ''เครื่องตี'' ทั้งหมด', '["ระนาดเอก ฆ้องวงใหญ่ ฉิ่ง กลองแขก","จะเข้ ซอด้วง ซออู้","ขลุ่ยเพียงออ ปี่ใน แคน","ซอสามสาย กระจับปี่ กรับ"]'::jsonb, '0'::jsonb, 'ระนาดเอก ฆ้องวง ฉิ่ง ฉาบ กรับ กลองแขก เป็นเครื่องดนตรีที่ใช้ไม้ตีหรือการกระทบกันให้เกิดเสียง จึงเป็นเครื่องตี', 'easy', '[ศ 2.1 ป.4/2] เครื่องดนตรีไทยประเภทตี'),
  ('ศิลปะ', 'ป.4', 'mcq', 'เครื่องดนตรีชิ้นเล็กๆ ที่ทำจากโลหะทองเหลือง ทำหน้าที่ควบคุมจังหวะหลักของวงดนตรีไทยคือข้อใด', '["ฉิ่ง","กรับพวง","กลองทัด","โหม่ง"]'::jsonb, '0'::jsonb, 'ฉิ่ง เป็นเครื่องกำกับจังหวะที่สำคัญที่สุดในวงดนตรีไทย ใช้ตีเสียง ''ฉิ่ง-ฉับ'' ควบคุมความช้า-เร็วของเพลง', 'easy', '[ศ 2.1 ป.4/3] จังหวะหน้าทับและเครื่องกำกับจังหวะ'),
  ('ศิลปะ', 'ป.4', 'mcq', 'เครื่องดนตรีประเภทเป่าที่ทำจากไม้ซางและเป็นสัญลักษณ์เอกลักษณ์ของภาคอีสานคือข้อใด', '["แคน","ขลุ่ยเพียงออ","ปี่จุม","ปี่แน"]'::jsonb, '0'::jsonb, 'แคน เป็นเครื่องดนตรีเป่าที่ทำจากไม้ไผ่ซางและมีลิ้นโลหะ มีเสียงไพเราะเป็นเอกลักษณ์ของชาวอีสาน', 'easy', '[ศ 2.2 ป.4/1] ดนตรีพื้นบ้านภาคอีสาน'),
  ('ศิลปะ', 'ป.4', 'mcq', 'การใช้นิ้วหัวแม่มือจรดข้อแรกของนิ้วชี้ แล้วกรีดนิ้วที่เหลือทั้งสามให้แผ่ตึงโค้ง เรียกว่ากิริยาใดในนาฏศิลป์ไทย', '["การจีบ","การตั้งวง","การล่อแก้ว","การกระดกเท้า"]'::jsonb, '0'::jsonb, 'การจีบ คือการนำปลายนิ้วหัวแม่มือมาจรดที่ข้อแรกของปลายนิ้วชี้ แล้วคลี่นิ้วกลาง นิ้วนาง นิ้วก้อยออกเป็นรูปพัด', 'easy', '[ศ 3.1 ป.4/1] นาฏยศัพท์ (การจีบ)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'การตั้งวงของตัวพระตัวนางที่ปลายนิ้วอยู่ระดับเดียวกับ ''ขมับหรือศีรษะ'' เรียกว่าการตั้งวงระดับใด', '["ตั้งวงบน","ตั้งวงกลาง","ตั้งวงล่าง","ตั้งวงหน้า"]'::jsonb, '0'::jsonb, 'ตั้งวงบน คือ ปลายนิ้วมืออยู่ระดับแง่ศีรษะ (ตัวพระ) หรือระดับหางคิ้ว/ขมับ (ตัวนาง)', 'easy', '[ศ 3.1 ป.4/1] นาฏยศัพท์ (การตั้งวง)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'การประสานมือทั้งสองทาบลงบริเวณหน้าอก เรียกว่าภาษาท่าทางนาฏศิลป์สื่อความหมายถึงสิ่งใด', '["ความรัก หรือ ความประทับใจ","ความโกรธ","ความเศร้าโศกเสียใจ","การปฏิเสธ"]'::jsonb, '0'::jsonb, 'ท่าประสานมือทาบที่หน้าอก เป็นภาษาท่าสื่อความหมายถึงความรัก ความยินดี หรือความปลาบปลื้มใจ', 'easy', '[ศ 3.1 ป.4/2] ภาษาท่าทางนาฏศิลป์ (ท่ารัก)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'การแสดงเงาหุ่นกระบอกที่ทำจากหนังวัวแกะสลักฉลุลาย เป็นการแสดงพื้นบ้านภาคใต้ข้อใด', '["หนังตะลุง","หุ่นละครเล็ก","ละครชาตรี","ลิเกฮูลู"]'::jsonb, '0'::jsonb, 'หนังตะลุงเป็นการละเล่นพื้นบ้านยอดนิยมของภาคใต้ ใช้รูปหุ่นหนังแกะสลักเชิดหลังจอผ้าขาวโดยมีตะเกียงฉายแสงให้เกิดเงา', 'easy', '[ศ 3.2 ป.4/1] การแสดงพื้นเมืองภาคใต้'),
  ('ศิลปะ', 'ป.4', 'mcq', 'ข้อใดเป็นมารยาทในการชมการแสดงดนตรีและนาฏศิลป์ที่เหมาะสมที่สุด', '["ปรบมือให้เกียรติเมื่อนักแสดงปรากฏตัวและเมื่อการแสดงจบลง","ส่งเสียงตะโกนคุยกับนักแสดง","ลุกเดินไปมาหน้าเวทีตลอดเวลา","เปิดเสียงโทรศัพท์มือถือดังๆ"]'::jsonb, '0'::jsonb, 'การปรบมือให้เกียรติผู้แสดง การรักษาความเงียบ และการปิดเสียงเครื่องมือสื่อสาร เป็นมารยาทสากลในการชมการแสดง', 'easy', '[ศ 3.2 ป.4/2] มารยาทในการชมการแสดง'),
  ('ศิลปะ', 'ป.4', 'mcq', 'สี 2 สีใดในวงจรสีธรรมชาติที่สามารถอยู่ได้ ''ทั้งวรรณะร้อนและวรรณะเย็น'' ขึ้นอยู่กับสีแวดล้อมข้างเคียง', '["สีเหลือง และ สีม่วง","สีแดง และ สีน้ำเงิน","สีเขียว และ สีส้ม","สีขาว และ สีดำ"]'::jsonb, '0'::jsonb, 'สีเหลืองและสีม่วงเป็นสีคนกลาง (Neutral tone) หากอยู่ร่วมกับกลุ่มสีร้อนจะกลายเป็นวรรณะร้อน หากอยู่กับกลุ่มสีเย็นจะกลายเป็นวรรณะเย็น', 'medium', '[ศ 1.1 ป.4/2] สีวรรณะกลาง (Neutral Colors)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'เมื่อแสงสว่างส่องกระทบวัตถุทรงกลมจากด้านบนซ้าย ด้านล่างขวาของวัตถุจะมีลักษณะอย่างไร', '["เป็นส่วนที่มืดที่สุด (เงาตกกระทบและเงาบนตัววัตถุ)","เป็นส่วนที่สว่างที่สุด (แสงไฮไลต์)","มีสีเดียวกับพื้นหลัง","มองไม่เห็นวัตถุเลย"]'::jsonb, '0'::jsonb, 'ด้านตรงข้ามกับทิศทางที่แสงส่องเข้ามาจะถูกบดบังแสง จึงเกิดเป็นเงาน้ำหนักเข้มบนตัววัตถุและทอดเป็นเงาตกทอดบนพื้น', 'medium', '[ศ 1.1 ป.4/3] น้ำหนักแสงเงา (Tone and Value)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'แม่สีขั้นที่ 1 ของสีวัตถุธาตุประกอบด้วย 3 สีใดบ้าง', '["สีแดง สีเหลือง สีน้ำเงิน","สีแดง สีเขียว สีน้ำเงิน","สีส้ม สีม่วง สีเขียว","สีขาว สีดำ สีเทา"]'::jsonb, '0'::jsonb, 'แม่สีขั้นที่ 1 ในทางทัศนศิลป์คือ แดง เหลือง น้ำเงิน ซึ่งเป็นสีตั้งต้นที่ไม่สามารถผสมขึ้นจากสีอื่นได้', 'medium', '[ศ 1.1 ป.4/4] แม่สีขั้นที่ 1 (Primary Colors)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'เมื่อนำแม่สี ''สีแดง'' มาผสมกับ ''สีน้ำเงิน'' ในอัตราส่วนเท่ากัน จะได้สีขั้นที่ 2 คือสีใด', '["สีม่วง","สีเขียว","สีส้ม","สีน้ำตาล"]'::jsonb, '0'::jsonb, 'สีแดง + สีน้ำเงิน = สีม่วง (ส่วน แดง + เหลือง = ส้ม, และ เหลือง + น้ำเงิน = เขียว)', 'medium', '[ศ 1.1 ป.4/5] การผสมสีขั้นที่ 2 (Secondary Colors)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'การใช้เทคนิค ''การขูดขีดสี'' (Scraffito) หรือการระบายสีหนาๆ จนเกิดมิติสัมผัส มุ่งเน้นสร้างสรรค์ทัศนธาตุข้อใด', '["พื้นผิว (Texture)","จังหวะ (Rhythm)","วรรณะสี (Color Tone)","รูปร่างเรขาคณิต (Geometric Shape)"]'::jsonb, '0'::jsonb, 'พื้นผิว (Texture) คือลักษณะภายนอกของวัตถุที่สามารถมองเห็นหรือสัมผัสได้ เช่น หยาบ ละเอียด เรียบ มัน ขรุขระ', 'medium', '[ศ 1.1 ป.4/6] พื้นผิวในงานทัศนศิลป์ (Texture)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'เหรียญกษาปณ์ (เช่น เหรียญสิบบาท หรือเหรียญบาท) จัดเป็นตัวอย่างของงานปั้นประเภทใด', '["งานปั้นนูนต่ำ","งานปั้นนูนสูง","งานปั้นลอยตัว","งานปั้นแม่พิมพ์หล่อ"]'::jsonb, '0'::jsonb, 'งานปั้นนูนต่ำ (Bas-Relief) คือรูปปั้นที่มีแผ่นหลังรองรับและนูนขึ้นมาจากพื้นเพียงเล็กน้อย เช่น ลวดลายบนเหรียญบาทหรือเหรียญพระเครื่อง', 'medium', '[ศ 1.1 ป.4/7] งานปั้นนูนต่ำ (Bas-Relief)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'เครื่องปั้นดินเผา ''ด่านเกวียน'' จังหวัดนครราชสีมา มีลักษณะเด่นเฉพาะตัวในเรื่องใด', '["เนื้อดินเหนียวมีแร่เหล็กผสม ทำให้เมื่อเผาแล้วมีสีน้ำตาลดำ แกร่งและเป็นมันวาว","มีสีขาวบริสุทธิ์เหมือนงาช้าง","ทำจากดินทรายแก้ว","เคลือบสีทองคำเปลว"]'::jsonb, '0'::jsonb, 'ดินด่านเกวียนเป็นดินเหนียวริมลำน้ำมูลที่มีแร่เหล็กปนอยู่มาก เมื่อนำไปเผาด้วยอุณหภูมิสูงจะกลายเป็นสีสัมฤทธิ์หรือสีสนิมเหล็ก แข็งแกร่งทนทาน', 'medium', '[ศ 1.2 ป.4/2] ภูมิปัญญาเครื่องปั้นดินเผาด่านเกวียน'),
  ('ศิลปะ', 'ป.4', 'mcq', 'วงดนตรีไทยที่ประกอบด้วยเครื่องตีเป็นหลัก (ระนาดเอก ระนาดทุ้ม ฆ้องวง กลอง) และเครื่องเป่า (ปี่) เรียกว่าวงประเภทใด', '["วงปี่พาทย์","วงเครื่องสาย","วงมโหรี","วงอังกะลุง"]'::jsonb, '0'::jsonb, 'วงปี่พาทย์ประกอบด้วยเครื่องตีและเครื่องเป่า ไม่มีเครื่องสาย มีเสียงดังกังวาน นิยมบรรเลงประกอบพิธีกรรมและการแสดงโขน ละคร', 'medium', '[ศ 2.1 ป.4/1] วงดนตรีไทย (วงปี่พาทย์)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'วงเครื่องสายไทย แตกต่างจากวงปี่พาทย์อย่างชัดเจนในเรื่องใด', '["ใช้เครื่องดนตรีประเภทเครื่องสาย (ซอด้วง ซออู้ จะเข้) เป็นหลัก และมีเสียงนุ่มนวล","ไม่มีจังหวะฉิ่ง","ใช้กลองขนาดใหญ่ตีเสียงดัง","ใช้เฉพาะเครื่องเป่าทองเหลือง"]'::jsonb, '0'::jsonb, 'วงเครื่องสายเน้นเครื่องดีดและเครื่องสี เสียงจะนุ่มนวล ไพเราะ เบาสบาย เหมาะสำหรับบรรเลงขับกล่อมในอาคาร', 'medium', '[ศ 2.1 ป.4/1] วงดนตรีไทย (วงเครื่องสาย)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'เครื่องดนตรีสากลในข้อใดจัดอยู่ในกลุ่ม ''เครื่องสาย'' (String Instruments) ทั้งหมด', '["ไวโอลิน วิโอลา เชลโล ดับเบิลเบส","ฟลูต คลาริเน็ต แซกโซโฟน","ทรัมเป็ต ทรอมโบน ทูบา","กลองทิมปานี กลองสแนร์"]'::jsonb, '0'::jsonb, 'ไวโอลิน วิโอลา เชลโล ดับเบิลเบส ฮาร์ป เป็นเครื่องดนตรีสากลที่ทำให้เกิดเสียงจากการสั่นสะเทือนของสาย', 'medium', '[ศ 2.1 ป.4/2] เครื่องดนตรีสากลประเภทเครื่องสาย (Strings)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'เครื่องดนตรีใดเป็นเครื่องเป่าลมไม้ที่มีลิ้นเดี่ยวและมีท่อลำตัวสีดำทำจากไม้หรืออีโบไนต์', '["คลาริเน็ต (Clarinet)","ทรัมเป็ต","ทรอมโบน","ไวโอลิน"]'::jsonb, '0'::jsonb, 'คลาริเน็ตเป็นเครื่องเป่าลมไม้ลิ้นเดี่ยว (Single reed) ทำจากไม้ มีคีย์โลหะสำหรับกดเปลี่ยนระดับเสียง', 'medium', '[ศ 2.1 ป.4/2] เครื่องเป่าลมไม้ (Woodwind)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'ระดับเสียงของโน้ตดนตรีสากล 7 ตัว เรียงลำดับจาก ''เสียงต่ำไปหาเสียงสูง'' ได้ถูกต้องตามข้อใด', '["โด เร มี ฟา ซอล ลา ที (C D E F G A B)","โด มี เร ฟา ลา ซอล ที","ที ลา ซอล ฟา มี เร โด","โด เร ฟา มี ซอล ที ลา"]'::jsonb, '0'::jsonb, 'บันไดเสียงเมเจอร์เรียงลำดับจากเสียงต่ำไปสูง: โด (C) - เร (D) - มี (E) - ฟา (F) - ซอล (G) - ลา (A) - ที (B)', 'medium', '[ศ 2.1 ป.4/3] ระดับเสียงโน้ตดนตรีสากล'),
  ('ศิลปะ', 'ป.4', 'mcq', 'กุญแจซอล (Treble Clef) บนบรรทัด 5 เส้น เริ่มต้นหมุนหัวกุญแจที่เส้นลำดับใด (นับจากเส้นล่างสุดขึ้นบน)', '["เส้นที่ 2","เส้นที่ 1","เส้นที่ 3","เส้นที่ 4"]'::jsonb, '0'::jsonb, 'หัวกุญแจซอลจะวนรอบคาบอยู่บนเส้นที่ 2 ของบรรทัด 5 เส้น เพื่อกำหนดว่าโน้ตที่อยู่บนเส้นที่ 2 คือเสียง ซอล (G)', 'medium', '[ศ 2.1 ป.4/4] สัญลักษณ์กุญแจซอล (Treble Clef)'),
  ('ศิลปะ', 'ป.4', 'mcq', '''เพลงเรือ'' และ ''เพลงอีแซว'' เป็นเพลงพื้นบ้านของภาคใดที่หนุ่มสาวนิยมร้องโต้ตอบเกี้ยวพาราสีกันอย่างสนุกสนาน', '["ภาคกลาง","ภาคเหนือ","ภาคใต้","ภาคอีสาน"]'::jsonb, '0'::jsonb, 'เพลงเรือ เพลงเกี่ยวข้าว เพลงอีแซว ลำตัด เป็นเพลงปฏิพากย์ (ร้องโต้ตอบ) ของชาวบ้านภาคกลางในเทศกาลน้ำหลากหรือฤดูเกี่ยวข้าว', 'medium', '[ศ 2.2 ป.4/1] เพลงพื้นบ้านภาคกลาง (เพลงเรือ)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'เครื่องดนตรีประเภทดีดที่ทำจากไม้สักและใช้บรรเลงร่วมในวงดนตรีสะล้อซอซึงของภาคเหนือคือเครื่องดนตรีใด', '["ซึง","สะล้อ","จะเข้","พิณโปร่ง"]'::jsonb, '0'::jsonb, 'ซึง เป็นเครื่องดนตรีประเภทดีดของล้านนา (ภาคเหนือ) มีสายโลหะ บรรเลงคลอกับสะล้อ (เครื่องสี) และขลุ่ย', 'medium', '[ศ 2.2 ป.4/2] เครื่องดนตรีพื้นบ้านภาคเหนือ (สะล้อ ซอ ซึง)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'การทำมือจีบโดยให้ ''ปลายนิ้วชี้ชี้ขึ้นด้านบน และหักข้อมือเข้าหาลำแขน'' เรียกว่าการจีบลักษณะใด', '["จีบหงาย","จีบคว่ำ","จีบปรกข้าง","จีบส่งหลัง"]'::jsonb, '0'::jsonb, 'จีบหงาย คือ การหงายฝ่ามือขึ้น ปลายนิ้วชี้ชี้ขึ้นด้านบนและหักข้อมือเข้าหาลำแขน (ถ้าคว่ำมือลง นิ้วชี้ลง เรียกจีบคว่ำ)', 'medium', '[ศ 3.1 ป.4/1] นาฏยศัพท์ (จีบหงาย vs จีบคว่ำ)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'การตั้งมือข้างหนึ่งระดับอกแล้วส่ายปลายนิ้วไปมาเบาๆ ในนาฏศิลป์ไทย เป็นภาษาท่าสื่อความหมายถึงสิ่งใด', '["การปฏิเสธ หรือคำว่า ''ไม่''","การเรียกให้เข้ามาหา","การไหว้ขอบคุณ","การโศกเศร้า"]'::jsonb, '0'::jsonb, 'การยกมือระดับอกแล้วส่ายข้อมือหรือปลายนิ้วไปมา เป็นภาษาท่าสื่อความหมายว่า ''ปฏิเสธ'' ไม่เอา หรือ ไม่ใช่', 'medium', '[ศ 3.1 ป.4/2] ภาษาท่าสื่อความหมาย (ท่าปฏิเสธ)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'เพลงแรกของรำวงมาตรฐานคือเพลง ''งามแสงเดือน'' ใช้ท่ารำมาตรฐานท่าใด', '["ท่าสอดสร้อยมาลา","ท่าแขกเต้าเข้ารัง","ท่าชักแป้งผัดหน้า","ท่ารำส่าย"]'::jsonb, '0'::jsonb, 'เพลงงามแสงเดือน ซึ่งเป็นเพลงลำดับที่ 1 ของรำวงมาตรฐาน 10 เพลง ใช้ท่ารำชื่อ ''ท่าสอดสร้อยมาลา''', 'medium', '[ศ 3.1 ป.4/3] รำวงมาตรฐาน (เพลงงามแสงเดือน)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'การแสดง ''ฟ้อนเล็บ'' ของภาคเหนือ มีเอกลักษณ์ที่โดดเด่นสะท้อนถึงวิถีชีวิตชาวล้านนาอย่างไร', '["ผู้แสดงสวมเล็บยาวทำจากทองเหลือง ท่ารำอ่อนช้อย อ่อนหวาน และเนิบช้าสง่างาม","จังหวะเต้นเร้าใจและรวดเร็ว","มีการกระโดดข้ามกระบอกไม้ไผ่","ใช้พัดประกอบการร่ายรำ"]'::jsonb, '0'::jsonb, 'ฟ้อนเล็บเป็นการฟ้อนต้อนรับแขกบ้านแขกเมืองของชาวเหนือ ช่างฟ้อนจะสวมเล็บทองเหลืองเรียวยาว ท่วงท่ารำอ่อนช้อยสงบนุ่มนวลตามจังหวะกลองแอว', 'medium', '[ศ 3.2 ป.4/1] การแสดงพื้นเมืองภาคเหนือ (ฟ้อนเล็บ)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'การแสดง ''เซิ้งกระติบข้าว'' สะท้อนให้เห็นวิถีชีวิตการประกอบอาชีพใดของชาวอีสาน', '["การทำไร่ทำนาและการนำอาหารใส่กระติบข้าวไปกินในทุ่งนา","การทำประมงในทะเล","การล่องเรือค้าขาย","การล่าสัตว์บนภูเขา"]'::jsonb, '0'::jsonb, 'เซิ้งกระติบข้าวสะท้อนวิถีชีวิตของหญิงสาวอีสานที่สะพายกระติบข้าวเหนียวไปส่งให้บิดาหรือสามีที่กำลังทำนา มีลีลาจังหวะสนุกสนานกระฉับกระเฉง', 'medium', '[ศ 3.2 ป.4/1] การแสดงพื้นเมืองภาคอีสาน (เซิ้งกระติบข้าว)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'ในการวาดภาพทิวทัศน์ให้ดูมีมิติความลึก (Perspective) สิ่งของที่อยู่ ''ใกล้ตัว'' จะต้องวาดอย่างไรเมื่อเทียบกับสิ่งของที่อยู่ ''ไกลตัว''', '["วาดให้มีขนาดใหญ่กว่าและมีรายละเอียดชัดเจนกว่า","วาดให้มีขนาดเล็กกว่าและเลือนรางกว่า","วาดให้มีขนาดเท่ากันทั้งหมด","ระบายด้วยสีดำอย่างเดียว"]'::jsonb, '0'::jsonb, 'หลักทัศนียวิทยา (Perspective): วัตถุที่อยู่ใกล้จะมองเห็นขนาดใหญ่ รายละเอียดชัด สีสด ส่วนวัตถุที่อยู่ไกลจะเล็กลง รายละเอียดลดลง และสีจางลง', 'medium', '[ศ 1.1 ป.4/1] จุดและเส้นในการวาดภาพทัศนียภาพ'),
  ('ศิลปะ', 'ป.4', 'mcq', 'เพลงไทยเดิมที่มีอัตราจังหวะปานกลาง ไม่ช้าและไม่เร็วเกินไป เรียกว่าจังหวะอัตราใด', '["อัตราจังหวะ 2 ชั้น","อัตราจังหวะ 3 ชั้น","อัตราจังหวะชั้นเดียว","อัตราจังหวะเพลงเร็ว"]'::jsonb, '0'::jsonb, 'เพลงไทยมี 3 อัตราจังหวะ: 3 ชั้น = ช้า, 2 ชั้น = ปานกลาง, ชั้นเดียว = เร็ว (เพลงเถา = ครบทั้ง 3 ชั้น)', 'medium', '[ศ 2.1 ป.4/3] จังหวะ 2 ชั้นในเพลงไทย'),
  ('ศิลปะ', 'ป.4', 'mcq', 'การก้าวเท้าข้างหนึ่งเฉียงไปข้างหน้า โดยให้ส้นเท้าวางลงพื้นก่อนแล้วเปิดส้นเท้าหลัง เรียกว่าท่าใด', '["ก้าวหน้า","ก้าวข้าง","กระดกหลัง","ซอยเท้า"]'::jsonb, '0'::jsonb, 'ก้าวหน้า คือ การก้าวเท้าข้างใดข้างหนึ่งไปข้างหน้า โดยวางส้นเท้าลงก่อนและเปิดส้นเท้าหลังขึ้นเล็กน้อย ลำตัวตั้งตรง', 'medium', '[ศ 3.1 ป.4/1] นาฏยศัพท์ส่วนเท้า (การยกเท้าและก้าวหน้า)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'ข้อควรระวังสำคัญที่สุดในการใช้ ''คัตเตอร์หรือมีดแกะสลัก'' ในงานศิลปะคือข้อใด', '["ต้องกรีดหรือแกะออกจากตัวเสมอ และเก็บใบมีดทุกครั้งหลังใช้งาน","ดึงใบมีดออกมาให้ยาวที่สุด","ใช้มือข้างที่ไม่ถนัดจับตรงคมมีด","เดินถือมีดแกะสลักวิ่งเล่นในห้อง"]'::jsonb, '0'::jsonb, 'การใช้ของมีคมต้องกรีดออกจากตัวเสมอเพื่อป้องกันไม่ให้มีดแฉลบเข้าหาตัว และต้องเลื่อนเก็บใบมีดทันทีเมื่อวาง', 'medium', '[ศ 1.1 ป.4/4] ความปลอดภัยในการใช้อุปกรณ์ศิลปะ'),
  ('ศิลปะ', 'ป.4', 'mcq', 'ตัวละครในวรรณคดีเรื่องรามเกียรติ์ข้อใด ที่ผู้แสดงโขน ''ไม่ต้องสวมหัวโขนปิดหน้า'' แต่สวมชฎาหรือมงกุฎแทน', '["ตัวพระ (เช่น พระราม, พระลักษมณ์)","ทศกัณฐ์ (ตัวยักษ์)","หนุมาน (ตัวลิง)","สุครีพ (ตัวลิง)"]'::jsonb, '0'::jsonb, 'ในการแสดงโขน ตัวพระ (พระราม พระลักษมณ์) และตัวนาง (นางสีดา) จะเปิดหน้าและสวมมงกุฎหรือชฎา ส่วนตัวยักษ์และลิงจะสวมหัวโขนครอบทั้งศีรษะ', 'medium', '[ศ 3.2 ป.4/1] การแสดงโขน'),
  ('ศิลปะ', 'ป.4', 'mcq', 'หากต้องการวาดภาพโปสเตอร์ให้มีความโดดเด่นสะดุดตาเป็นพิเศษตามหลัก ''สีคู่ตรงข้าม'' (Complementary Colors) ควรจับคู่สีข้อใด', '["สีแดง กับ สีเขียว","สีแดง กับ สีส้ม","สีน้ำเงิน กับ สีฟ้า","สีเหลือง กับ สีเขียวอ่อน"]'::jsonb, '0'::jsonb, 'สีแดงและสีเขียวเป็นสีคู่ตรงข้ามในวงจรสี (180 องศา) เมื่อวางคู่กันจะขับเน้นให้กันและกันดูสดใสและเด่นชัดสะดุดตาที่สุด', 'hard', '[ศ 1.1 ป.4/2] การใช้คู่สีตรงข้าม (Complementary Colors)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'การจัดองค์ประกอบศิลป์แบบ ''ความสมดุลแบบสองข้างไม่เท่ากัน'' (Asymmetrical Balance) มีลักษณะเด่นอย่างไร', '["น้ำหนักสายตาทั้งสองข้างสมดุลกันด้วยการจัดวางรูปทรง สี หรือพื้นผิว แม้ว่ารูปร่างของวัตถุทั้งสองข้างจะไม่เหมือนกัน","ทั้งสองข้างซ้ายขวาต้องมีรูปร่างและขนาดเหมือนกันทุกประการเหมือนส่องกระจก","มีวัตถุอยู่ตรงกลางภาพเพียงชิ้นเดียว","ภาพมีน้ำหนักเอียงไปด้านใดด้านหนึ่งจนดูขาดความสมดุล"]'::jsonb, '0'::jsonb, 'ความสมดุลแบบอสมมาตร (Asymmetry) คือการจัดวางองค์ประกอบซ้าย-ขวาที่ไม่เหมือนกัน แต่ให้ความรู้สึกของน้ำหนักทางสายตาที่สมดุลและน่าสนใจ', 'hard', '[ศ 1.1 ป.4/3] การวิเคราะห์เอกภาพและความสมดุล (Composition)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'ข้อใดจำแนกกระบวนการสร้างงานประติมากรรมระหว่าง ''การปั้น'' (Modeling) กับ ''การแกะสลัก'' (Carving) ได้ถูกต้อง', '["การปั้นเป็นกระบวนการเพิ่มพูนวัสดุ (Additive process) ส่วนการแกะสลักเป็นกระบวนการตัดทอนเนื้อวัสดุออก (Subtractive process)","การปั้นทำได้เฉพาะหิน ส่วนการแกะสลักทำได้เฉพาะดินเหนียว","การปั้นมี 2 มิติ ส่วนการแกะสลักมี 3 มิติ","ทั้งสองกรรมวิธีไม่มีความแตกต่างกันในทางศิลปะ"]'::jsonb, '0'::jsonb, 'การปั้น (ดินเหนียว ขี้ผึ้ง) คือการพอกพูนเพิ่มเนื้อวัสดุ ส่วนการแกะสลัก (ไม้ หินอ่อน สบู่) คือการสลักตัดเฉือนส่วนที่ไม่ต้องการออก', 'hard', '[ศ 1.1 ป.4/5] การวิเคราะห์กรรมวิธีงานปั้นและแกะสลัก'),
  ('ศิลปะ', 'ป.4', 'mcq', 'เหตุใด ''ขลุ่ยเพียงออ'' ที่ทำจากไม้ไผ่ และ ''ฟลูต'' (Flute) ที่ทำจากโลหะเงิน เมื่อเป่าโน้ตเสียงเดียวกัน (เช่น โน้ต โด) จึงมีเอกลักษณ์ของเสียง (Timbre) แตกต่างกัน', '["เพราะความแตกต่างของวัสดุ รูปทรงท่อลม และกำทอนของคลื่นเสียงที่ทำให้เกิดโครงสร้างโอเวอร์โทนเฉพาะตัว","เพราะโน้ตโดของไทยกับสากลไม่เท่ากัน","เพราะคนเป่าเป็นคนละคน","เพราะเป่าในเวลาที่ต่างกัน"]'::jsonb, '0'::jsonb, 'สีสันของเสียง (Timbre) เกิดจากวัสดุ โครงสร้างเครื่องดนตรี และฮาร์มอนิกส์/โอเวอร์โทนที่สะท้อนออกมา ทำให้หูเราแยกแยะชนิดเครื่องดนตรีได้', 'hard', '[ศ 2.1 ป.4/1] การวิเคราะห์ความแตกต่างของเสียงเครื่องดนตรี (Timbre)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'ในอัตราจังหวะ 4/4 ถ้า ''โน้ตตัวกลม'' (Whole note) มีค่าเท่ากับ 4 จังหวะ โน้ตตัวดำ 2 ตัว รวมกับโน้ตตัวขาว 1 ตัว จะมีค่ารวมกี่จังหวะ', '["4 จังหวะ (เท่ากับโน้ตตัวกลม 1 ตัวพอดี)","3 จังหวะ","5 จังหวะ","6 จังหวะ"]'::jsonb, '0'::jsonb, 'ในจังหวะ 4/4: โน้ตตัวดำมีค่าตัวละ 1 จังหวะ (2 ตัว = 2 จังหวะ) โน้ตตัวขาวมีค่า 2 จังหวะ รวมเป็น 2 + 2 = 4 จังหวะ เท่ากับโน้ตตัวกลม 1 ตัว', 'hard', '[ศ 2.1 ป.4/3] ค่าของตัวโน้ตและจังหวะสากล (Note Values)'),
  ('ศิลปะ', 'ป.4', 'mcq', 'เหตุใด ''วงมโหรี'' จึงต้องมีการย่อขนาดเครื่องตี (เช่น ระนาดเอกมโหรี ฆ้องวงมโหรี) ให้มีขนาดเล็กกว่าวงปี่พาทย์ทั่วไป', '["เพื่อให้ระดับเสียงและความดังกลมกลืนพอดีกับเครื่องสายและเครื่องขับร้อง ไม่ดังกลบเสียงซอและจะเข้","เพื่อประหยัดไม้ในการสร้าง","เพื่อให้เด็กตัวเล็กๆ สามารถเล่นได้","เพราะไม่มีพื้นที่จัดวางในวัง"]'::jsonb, '0'::jsonb, 'วงมโหรีเป็นการผสมผสานระหว่างวงปี่พาทย์และวงเครื่องสาย จึงต้องย่อขนาดและระดับเสียงเครื่องตีลงเพื่อให้กลมกลืนกับเครื่องสายที่มีเสียงเบานุ่ม', 'hard', '[ศ 2.2 ป.4/1] วัฒนธรรมดนตรีมโหรีราชสำนัก'),
  ('ศิลปะ', 'ป.4', 'mcq', 'ในการตั้งวงบน ข้อใดอธิบายความแตกต่างระหว่าง ''ตัวพระ'' กับ ''ตัวนาง'' ได้ถูกต้องตามหลักนาฏศิลป์ไทย', '["ตัวพระจะกันข้อศอกออกกว้าง ปลายนิ้วอยู่ระดับแง่ศีรษะ ส่วนตัวนางจะหนีบศอกเข้ามา ปลายนิ้วอยู่ระดับหางคิ้ว","ตัวพระห้ามยกแขนสูงเกินระดับอก","ตัวนางต้องกางข้อศอกให้กว้างที่สุดกว่าตัวพระ","ทั้งสองตัวละครมีท่าทางการตั้งวงที่เหมือนกันทุกองศา"]'::jsonb, '0'::jsonb, 'ตัวพระเป็นตัวแทนบุรุษ ท่ารำจะเปิดศอกกว้าง สง่างาม ผึ่งผาย ส่วนตัวนางเป็นสตรี ท่ารำจะละมุน หนีบศอกเข้ามาใกล้ลำตัว อ่อนหวาน นุ่มนวล', 'hard', '[ศ 3.1 ป.4/1] การเปรียบเทียบลักษณะท่ารำตัวพระและตัวนาง'),
  ('ศิลปะ', 'ป.4', 'mcq', 'ข้อใดจับคู่ ''การแสดงพื้นบ้าน'' กับ ''ภูมิภาคและลักษณะทางวัฒนธรรม'' ได้อย่างถูกต้องสมบูรณ์', '["ระบำตารีกีปัส - ภาคใต้ (ใช้อุปกรณ์พัด สะท้อนวัฒนธรรมมลายู)","ฟ้อนเทียน - ภาคใต้ (จังหวะรวดเร็วคึกคัก)","เซิ้งสวิง - ภาคเหนือ (อ่อนหวานเนิบช้า)","เต้นกำรำเคียว - ภาคอีสาน (สะท้อนการจับปลาในทะเล)"]'::jsonb, '0'::jsonb, 'ระบำตารีกีปัสเป็นการแสดงระบำพัดของชาวไทยมุสลิมภาคใต้ (ตารี = ระบำ, กีปัส = พัด) ลีลาพริ้วไหวงดงาม', 'hard', '[ศ 3.2 ป.4/1] การวิเคราะห์อัตลักษณ์การแสดง 4 ภาค'),
  ('ศิลปะ', 'ป.4', 'mcq', 'ลวดลายบน ''ผ้ามัดหมี่'' ของภาคอีสาน และ ''ผ้าบาติก'' ของภาคใต้ มีกระบวนการสร้างลวดลายแตกต่างกันอย่างไร', '["ผ้ามัดหมี่มัดย้อมเส้นไหมหรือฝ้ายก่อนนำไปทอ ส่วนผ้าบาติกใช้เทียนเขียนกั้นสีย้อมลงบนผืนผ้าสำเร็จรูป","ผ้ามัดหมี่ใช้วิธีพิมพ์ลายด้วยเครื่องจักร ส่วนผ้าบาติกใช้การปักดิ้นทอง","ทั้งสองผืนใช้วิธีการวาดภาพระบายสีน้ำมันเหมือนกัน","ผ้าบาติกทำจากเปลือกไม้ ส่วนผ้ามัดหมี่ทำจากพลาสติก"]'::jsonb, '0'::jsonb, 'ผ้ามัดหมี่ใช้ภูมิปัญญาการมัดย้อมลวดลายบนเส้นด้าย/ไหมก่อนทอเป็นผืนผ้า ส่วนผ้าบาติกใช้ขี้ผึ้ง/เทียนร้อนเขียนลวดลายบนผ้าแล้วนำไปย้อมสี', 'hard', '[ศ 1.2 ป.4/1] ภูมิปัญญาลวดลายผ้าทอไทย'),
  ('ศิลปะ', 'ป.4', 'mcq', 'เมื่อตัวละครในนาฏศิลป์ไทยต้องการสื่ออารมณ์ ''โศกเศร้า ร้องไห้ เสียใจอย่างยิ่ง'' จะต้องใช้ภาษาท่าตามข้อใด', '["มือซ้ายตั้งวงบน มือขวาใช้ผ้าเช็ดหน้าหรือปลายนิ้วแตะที่ใต้ตา ค้อมศีรษะและสะอื้นไหล่เบาๆ","กระทืบเท้าทั้งสองข้างพร้อมกันและชี้นิ้ว","เอามือทาบอกและยิ้มแย้ม","กระโดดตบมือเหนือศีรษะ"]'::jsonb, '0'::jsonb, 'ท่าร้องไห้ในนาฏศิลป์ไทย ตัวละครจะนำมือแตะซับน้ำตาที่ใต้ตา ก้มหน้า และใช้ไหล่สะเทือนเป็นจังหวะเบาๆ แสดงความสะอึกสะอื้นอย่างมีศิลปะ', 'hard', '[ศ 3.1 ป.4/2] การวิเคราะห์ภาษาท่าสื่ออารมณ์ขั้นสูง');
